static void early_main(void){memset(&c,0,sizeof c);c.rom=rom_data;c.rom_size=sizeof rom_data;c.audio_mode=AUDIO_MUTE;c.sr=0x2700;c.io_tx[0]=c.io_tx[1]=0xff;c.io_tx[2]=0xfb;c.a[7]=read_mem(&c,0,4);c.ssp=c.a[7];c.pc=read_mem(&c,4,4)&0xffffff;memset(&mouse,0,sizeof mouse);mouse.enabled=1;memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&c);em_web_campaign.frontend_hold=1;rendered=0;unsigned masked=0;uint64_t seen=UINT64_MAX,end=10000;while(c.vdp.frames<end){step();if(c.vdp.rendered_frames!=seen){seen=c.vdp.rendered_frames;if(em_web_campaign.main_choices_generation==em_web_campaign.scene_generation&&!em_web_campaign.main_ready_generation){before=c;const uint8_t*clean=em_web_frame_textless(&c,2);check(clean!=NULL&&!memcmp(&before,&c,sizeof c),"early Main completed-frame mask readonly");unsigned changed=0;for(unsigned y=0;y<224;y++)for(unsigned x=0;x<320;x++){unsigned at=(y*320+x)*3;if(memcmp(clean+at,c.vdp.frame+at,3)){check(x>=104&&x<248&&y>=156&&y<188,"early Main mask preserves complete planet/logo/copyright");++changed;}}if(changed)++masked;}}if(em_web_campaign.main_ready_generation&&em_web_campaign_scene_ready(&c))break;}check(masked>5,"native choice writer is masked before first interactive Main poll");printf("PASS genuine cold Main: %u visible native choice frames cleaned before178D2, original planet/art outside choices unchanged\n",masked);fflush(stdout);}
